-- Isolated staging only. Every synthetic stock and revenue change rolls back.
\set ON_ERROR_STOP on
begin;
select set_config('request.jwt.claim.sub','',true);
create temp table pos_fixture(a uuid,m uuid,staff uuid,p uuid,b uuid,r uuid,c uuid,map uuid,job uuid,post uuid,rev uuid);
insert into pos_fixture select gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,gen_random_uuid(),gen_random_uuid();
grant select,update on pos_fixture to authenticated;
insert into public.branches(id,name) select a,'POS stock test' from pos_fixture;
insert into auth.users(id,email) select m,m::text||'@pos.invalid' from pos_fixture union all select staff,staff::text||'@pos.invalid' from pos_fixture;
insert into public.users(id,branch_id,role,status) select m,a,'manager','active' from pos_fixture union all select staff,a,'staff','active' from pos_fixture on conflict(id) do update set branch_id=excluded.branch_id,role=excluded.role,status=excluded.status;
select set_config('request.jwt.claim.sub',m::text,true) from pos_fixture;
insert into public.inventory_master(id,branch_id,product,category,unit,soll,is_active) select p,a,'POS test ingredient','Test','kg',10,true from pos_fixture;
insert into public.stock_batches(id,branch_id,product,category,unit,qty,received_date,expiry_date,status) select b,a,'POS test ingredient','Test','kg',10,current_date,current_date+10,'active' from pos_fixture;
select set_config('request.jwt.claim.sub',m::text,true) from pos_fixture;
set local role authenticated;
do $$declare f record;payload jsonb;bad_recipe uuid:=gen_random_uuid();bad_mapping uuid:=gen_random_uuid();begin select * into f from pos_fixture;
 perform public.configure_pos_connection(f.a,f.c,'Test till',true);
 perform public.save_inventory_recipe(f.a,f.r,'Test two portions',2,null,jsonb_build_array(jsonb_build_object('product_id',f.p,'qty',1,'unit','kg')),false);
 payload:=jsonb_build_object('format','schnitzery-pos-items-v1','currency','EUR','external_id','TEST-ITEM-EXPORT','days',jsonb_build_array(jsonb_build_object('date',current_date,'gross_sales',20)),'items',jsonb_build_array(jsonb_build_object('date',current_date,'sku','TEST-SKU','qty',4)));
 update pos_fixture set job=public.import_pos_export(f.a,f.c,payload);
 select * into f from pos_fixture;
 perform public.review_pos_import(f.a,f.job,true,'Source totals checked');
 begin perform public.post_pos_stock(f.a,f.job,f.post,'{}','Missing mapping',true);raise exception 'Unmapped SKU consumed stock';exception when unique_violation then null;end;
 if (select remaining_qty from public.stock_batches where id=f.b)<>10 or exists(select 1 from public.pos_stock_posts where import_id=f.job) then raise exception 'Failed post leaked stock';end if;
 perform public.save_inventory_recipe(f.a,bad_recipe,'Deliberately excessive test recipe',1,null,jsonb_build_array(jsonb_build_object('product_id',f.p,'qty',100,'unit','kg')),false);
 perform public.save_pos_recipe_mapping(f.a,bad_mapping,f.c,'TEST-SKU',bad_recipe,'Test shortage before correct mapping');
 begin perform public.post_pos_stock(f.a,f.job,gen_random_uuid(),jsonb_build_object('TEST-SKU',bad_mapping),'Test insufficient stock',true);raise exception 'Insufficient stock accepted';exception when unique_violation then null;end;
 if (select remaining_qty from public.stock_batches where id=f.b)<>10 or exists(select 1 from public.pos_stock_posts where import_id=f.job) or exists(select 1 from public.stock_batch_actions where branch_id=f.a) then raise exception 'Insufficient stock leaked allocations';end if;
 perform public.save_pos_recipe_mapping(f.a,f.map,f.c,'TEST-SKU',f.r,'Recipe and selling unit verified');
 perform public.post_pos_stock(f.a,f.job,f.post,jsonb_build_object('TEST-SKU',f.map),'Recipe usage checked',true);
 perform public.post_pos_stock(f.a,f.job,f.post,jsonb_build_object('TEST-SKU',f.map),'Recipe usage checked',true);
 if (select remaining_qty from public.stock_batches where id=f.b)<>8 or (select count(*) from public.pos_stock_lines where post_id=f.post)<>1 then raise exception 'Recipe scaling/retry incorrect';end if;
 begin perform public.post_pos_stock(f.a,f.job,gen_random_uuid(),jsonb_build_object('TEST-SKU',f.map),'Duplicate posting',true);raise exception 'Duplicate consumption allowed';exception when unique_violation then null;end;
 perform public.reverse_pos_stock(f.a,f.post,f.rev,'Mistaken recipe selection',true);
 perform public.reverse_pos_stock(f.a,f.post,f.rev,'Mistaken recipe selection',true);
 if (select remaining_qty from public.stock_batches where id=f.b)<>10 or (select amount from public.daily_sales where branch_id=f.a and sale_date=current_date)<>20 then raise exception 'Reversal changed revenue or failed to restore stock';end if;
 perform public.post_pos_stock(f.a,f.job,gen_random_uuid(),jsonb_build_object('TEST-SKU',f.map),'Corrected consumption reviewed',true);
 if (select remaining_qty from public.stock_batches where id=f.b)<>8 then raise exception 'Corrected repost failed';end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub',staff::text,true) from pos_fixture;
set local role authenticated;
do $$declare f record;begin select * into f from pos_fixture;
 if exists(select 1 from public.pos_stock_posts) then raise exception 'Staff read cost evidence';end if;
 begin perform public.post_pos_stock(f.a,f.job,gen_random_uuid(),'{}','Staff attempt',true);raise exception 'Staff consumed POS stock';exception when insufficient_privilege then null;end;
 raise notice 'PASS: normalized item import, reviewed mappings, recipe scaling, exact retries, rollback, reversal/repost and staff denial';
end $$;
reset role;
rollback;
